import java.util.*;

class Solution {
    public boolean searchBST(TreeNode root, int target) {
        TreeNode current = root;
        while (current != null) {
            if (current.val == target) {
                return true;
            }
            if (target < current.val) {
                current = current.left;
            } else {
                current = current.right;
            }
        }
        return false;
    }
}
